<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientJwksJsonVO;

final class TrustedClientJwksJsonVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = 'one';
        $ref = TrustedClientJwksJsonVO::from($value);
        $this->assertEquals('one', $ref->value());
        $other = TrustedClientJwksJsonVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = TrustedClientJwksJsonVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = TrustedClientJwksJsonVO::tryFrom(1, $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(TrustedClientJwksJsonVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = TrustedClientJwksJsonVO::from('one');
        $same = TrustedClientJwksJsonVO::from('one');
        $other = TrustedClientJwksJsonVO::from('other');
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
    public function test_empty(): void
    {
        $ref = TrustedClientJwksJsonVO::empty();
        $this->assertNull($ref->value());
    }
    public function test_try_from_empty(): void
    {
        $ref = TrustedClientJwksJsonVO::tryFrom(null, new ConstraintFailList());
        $this->assertNull($ref->value());
    }
}
